import{z as l,x as s,o as B,c as d,q as n,j as t,D as A,d as a,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"团队协作与评审","description":"","frontmatter":{"title":"团队协作与评审","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-team-review.md","filePath":"llm/ti-team-review.md","lastUpdated":1791063341000}'),p={name:"llm/ti-team-review.md"};function D(m,E,u,f,h,C){const r=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="团队协作与评审" tabindex="-1">团队协作与评审 <a class="header-anchor" href="#团队协作与评审" aria-label="Permalink to &quot;团队协作与评审&quot;">​</a></h1><div class="epigraph"><p>训练是团队运动：一场数周的 run 跨越多个假期与多人的注意力周期，没有协作制度的团队，靠运气衔接交接。</p><footer>—— 据大规模预训练团队的值班与评审实践整理</footer></div><p><a href="/llm/ti-recipe-management">上一课</a>把配置变成可评审的版本，而评审、值班、交接都要有人与流程承接。本课写团队协作与评审：run 怎么有负责人、会怎么开、长跑怎么值班、知识怎么流动。基础设施到此从物转向人——仪表盘、跟踪库、配方库、死因档案，只有在协作制度里被使用，才从存储变成组织的判断力。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>协作失败有三种典型。<strong>无主 run</strong>：长跑没有唯一负责人，尖峰发生时三个人都在等别人看一眼，处置延迟以小时计；事后无人能还原改过什么。<strong>汇报式评审</strong>：周会看截图听叙事，评审者无法回放到曲线与配置，「上周很好」式的汇报替代了数据；决策依据散会即失传。<strong>值班空转</strong>：绊网自动响应之后无人兜底，夜间触发的三级事件没人接手，回退动作卡在「等早上」——自动化把响应时间从小时缩到秒，前提是升级链上有人。</p><p><span class="marginnote">常见误区：初学者容易以为「群里人多，总会有人处理」——社会心理学称之为责任分散：旁观者越多，每个人越觉得不关自己的事。这正是无主 run 尖峰没人看的根源；唯一 owner 的作用，就是把「总会有人」变成「此刻是谁」。</span></p><h3 id="协作的最小制度" tabindex="-1">协作的最小制度 <a class="header-anchor" href="#协作的最小制度" aria-label="Permalink to &quot;协作的最小制度&quot;">​</a></h3><p>制度四件。<strong>负责人制</strong>：每场 run 启动时指定唯一 owner，写进配方治理组；owner 不必亲手值班，但对处置与归档负最终责任。<strong>决策日志</strong>：方向调整、配方升版、杀 run 决定，各写一条——决策、依据（链接到曲线与配方版本）、执行人、日期；日志进跟踪库，与 run 条目互链。<strong>值班轮换</strong>：长跑期间按周轮值，升级链写明「绊网二级找谁、三级找谁」，交接班记录挂在 run 条目下。<strong>评审双轨</strong>：配方与归档走异步轻评审，方向与预算走周期性评审会——两轨共用上一课的评审分级。</p><p><span class="marginnote">评审会的准入题：评审者到会前必须能答「这条曲线与基线差在哪个变量」。答不出的问题不进会场，先去补配置 diff——这一条把评审会从汇报会拉回决策会。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>评审会的开法按数据先行三步。会前：材料就是跟踪库的实时链接与拟决策的配方 diff，无截图无 PPT。会中：每项议程先对曲线（判读课的口径），再对证据链（归档课的指针），最后表决；表决结果当场写进决策日志，含反对意见——让日后复盘能分清「无人反对」与「反对未被采纳」。会后：决策的执行走配方升版或调度变更，状态可查。值班侧配套 runbook：尖峰、NaN、节点掉线、存储满四类高频事故的处置预案各一页，与绊网的分级响应衔接——自动化处理一级二级，人按手册处理三级与未知。</p>',11)),(B(),t(i,null,{default:A(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22run%20%E5%90%AF%E5%8A%A8%3A%20%E6%8C%87%E5%AE%9A%20owner%22%5D%20--%3E%20DUTY%5B%22%E5%80%BC%E7%8F%AD%E8%BD%AE%E6%8D%A2%20%2B%20%E5%8D%87%E7%BA%A7%E9%93%BE%22%5D%0A%20%20RUN%20--%3E%20MTG%7B%22%E8%AF%84%E5%AE%A1%E5%8F%8C%E8%BD%A8%22%7D%0A%20%20MTG%20--%3E%7C%E9%85%8D%E6%96%B9%E4%B8%8E%E5%BD%92%E6%A1%A3%7C%20ASY%5B%22%E5%BC%82%E6%AD%A5%E8%BD%BB%E8%AF%84%E5%AE%A1%3A%20diff%20%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20MTG%20--%3E%7C%E6%96%B9%E5%90%91%E4%B8%8E%E9%A2%84%E7%AE%97%7C%20SYNC%5B%22%E8%AF%84%E5%AE%A1%E4%BC%9A%3A%20%E5%AE%9E%E6%97%B6%E9%93%BE%E6%8E%A5%20%2B%20diff%22%5D%0A%20%20SYNC%20--%3E%20VOTE%5B%22%E8%A1%A8%E5%86%B3%20%2B%20%E5%BC%82%E8%AE%AE%E5%85%A5%E5%86%B3%E7%AD%96%E6%97%A5%E5%BF%97%22%5D%0A%20%20VOTE%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%3A%20%E9%85%8D%E6%96%B9%E5%8D%87%E7%89%88%20%2F%20%E8%B0%83%E5%BA%A6%E5%8F%98%E6%9B%B4%22%5D%0A%20%20INC%5B%22%E4%B8%89%E7%BA%A7%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20ESC%5B%22%E6%8C%89%E5%8D%87%E7%BA%A7%E9%93%BE%E6%89%BE%E4%BA%BA%22%5D%0A%20%20ESC%20--%3E%20RB%5B%22%E6%8C%89%20runbook%20%E5%A4%84%E7%BD%AE%22%5D%0A%20%20RB%20--%3E%20LOG%5B%22%E4%BA%A4%E6%8E%A5%E7%8F%AD%E8%AE%B0%E5%BD%95%E6%8C%82%20run%20%E6%9D%A1%E7%9B%AE%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("这套制度有效的机理是"),e("strong",null,"决策与证据绑定"),a("：决策日志强制每条决定带依据链接，事后审计与复盘有链可循；记录异议则是给未来的自己留证据——组织的记忆不止要记结论，还要记分歧。负责人制的机理是消除责任分摊：单一 owner 把「大家都在看」的社会惰性变成「此刻轮到谁」，升级链让责任在时间轴上也可分配。数据先行的机理是拉平信息差：实时链接让评审者与汇报者看同一份数据， Highest-paid-person 的叙事失去载体，争论收敛到配置 diff 与曲线形状这些可核对的对象上。")],-1)),(B(),t(i,null,{default:A(()=>[o(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E5%A4%9C%E9%97%B4%E5%B0%96%E5%B3%B0%E8%A7%A6%E5%8F%91%E4%B8%89%E7%BA%A7%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20A%5B%22%E6%97%A0%E5%88%B6%E5%BA%A6%3A%20%E4%B8%89%E4%BA%BA%E4%BA%92%E7%9B%B8%E7%AD%89%E5%BE%85%22%5D%0A%20%20A%20--%3E%20D%5B%22%E6%95%B0%E5%B0%8F%E6%97%B6%E5%90%8E%E6%9C%89%E4%BA%BA%E7%9C%8B%E5%88%B0%22%5D%0A%20%20D%20--%3E%20LOSE%5B%22%E5%A4%84%E7%BD%AE%E5%BB%B6%E8%BF%9F%3A%20%E5%BA%9F%E6%95%B0%E6%8D%AE%E4%B8%8E%E8%AF%AF%E5%88%A4%22%5D%0A%20%20S%20--%3E%20B%5B%22%E6%9C%89%E5%88%B6%E5%BA%A6%3A%20%E5%8D%87%E7%BA%A7%E9%93%BE%E5%91%BC%E5%8F%AB%E5%80%BC%E6%97%A5%20owner%22%5D%0A%20%20B%20--%3E%20P%5B%22%E5%80%BC%E6%97%A5%E8%80%85%E6%8C%89%20runbook%20%E5%A4%84%E7%BD%AE%22%5D%0A%20%20P%20--%3E%20OK%5B%22%E7%95%99%E7%97%95%3A%20%E5%A4%84%E7%BD%AE%E5%86%99%E8%BF%9B%E4%BA%A4%E6%8E%A5%E4%B8%8E%E5%86%B3%E7%AD%96%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">直觉类比：决策日志里的异议记录像判决书里的少数意见——判决按多数走，但少数理由留在纸上。半年后复盘时，你才能分清「当时没人想到」与「有人提醒过但被否了」，这是组织学习里最值钱的一条分界线。</span></p><p>值班与自动化的分工机理沿用绊网课的分级：机器处理已知模式（快、可复制），人处理未知与升级（慢、有判断）；手册是两者的接口，把个人处置经验固化成组织可执行的文本。</p><p><span class="marginnote">术语翻译：runbook 就是把某类事故的处置步骤写成的一页操作手册，像飞机的应急检查单——尖峰先查什么、回退按哪一步走、通知谁。它的价值在于夜里三点值班的人不需要灵感、只需要照单执行；个人经验借它固化成组织能力。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管协作流程，不管人的绩效评价：评审记录与死因档案不作个人问责依据，免责纪律（归档课已立）同样约束评审——问责文化一出现，配置 diff 会先学会藏。也不管跨团队的资源仲裁：份额与优先级之争归调度课的公平机制，本课的评审会只消费它的记账数据。制度的粒度要随团队规模分档：三五个人的小组，决策日志加值班表可能已够；制度是为补当前最短的板，不是为齐全。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每场 run 唯一 owner，写进配方治理组；处置与归档有最终责任人。</li><li>决策日志四要素：决策、依据链接、执行人、日期；异议与结论同权入档。</li><li>评审双轨：异步轻评审看 diff，评审会看实时数据，准入题过滤未读数的讨论。</li><li>值班与绊网分级衔接：机器处理已知，人按 runbook 处理三级与未知。</li><li>出处：据大规模训练团队的值班、交接与评审实践整理；分级响应见<a href="/llm/ti-numerical-health">数值健康检查</a>。</li></ul>',7))])}const _=l(p,[["render",D]]);export{g as __pageData,_ as default};
